node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Full product row
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('=== PRODUCT ROW ===');
console.log(JSON.stringify(product, null, 2));

// Check rt_variants table
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-73FAB4'\").all();
console.log('\n=== RT_VARIANTS ===');
console.log(JSON.stringify(variants, null, 2));

// Check variants_json field parsed
console.log('\n=== VARIANTS_JSON PARSED ===');
console.log(JSON.parse(product.variants_json || '[]'));

// Compatible products names
const compatIds = JSON.parse(product.compatible_with_json || '[]');
if (compatIds.length) {
  const placeholders = compatIds.map(() => '?').join(',');
  const compatProducts = db.prepare('SELECT product_id, name FROM products WHERE product_id IN (' + placeholders + ')').all(...compatIds);
  console.log('\n=== COMPATIBLE PRODUCTS ===');
  console.log(JSON.stringify(compatProducts, null, 2));
}
"
